#include <math.h>
int main(){int W=2400,H=1800,x,y;FILE*f=fopen("reconstructed.ppm","w");fprintf(f,"P3\n%d %d\n255\n",W,H);for(y=0;y<H;y++)for(x=0;x<W;x++){int r,g,b;double X=x-1199.5,Y=y-994.,dx=X/185.,dy=Y/185.,d=dx*dx+dy*dy;
if(y<900){double t=(900-y)/900.,u=X/1200.;r=191-50*t+13*u*u*t;g=217-27*t+7*u*u*t;b=255;}
else{double z=y-900.;int ix=(int)floor(1.5*X/z),iz=(int)floor(600/z);int q=((ix+iz)&1)==0?152:67;r=g=b=q;
/* long cast shadow, strongest near its axis */
 double a=(X+0.7*(y-1080))/420.,e=(y-1160)/150.;double s=a*a+e*e;
 if(s<1){int k=s<.45?20:46;r=g=b=k;}
}
if(d<1){double nx=dx,ny=dy,nz=sqrt(1-d),L=(.55*nx+.2*ny+.8*nz);if(L<0)L=0;r=51+(int)(145*L);g=10+(int)(29*L);b=g;}
/* sphere's lower edge is in front of the ground */
fprintf(f,"%d %d %d\n",r,g,b);}fclose(f);return 0;}

