if(y<900){double t=(900-y)/900.,u=X/1200.;r=191-60*t+15*t*t+u*u*(13*t+16*t*(1-t));g=217-35*t+8*t*t+u*u*(7*t+8*t*(1-t));b=255;}
else{double z=y-900.;int ix=(int)floor(1.5*X/z),iz=(int)floor(600/z);int q=((ix+iz)&1)==0?152:67;r=g=b=q;
/* long cast shadow, strongest near its axis */
 double u=(-2*X+y-1100)/2.236/520.,v=(X+2*(y-1100))/2.236/125.;double s=u*u+v*v;
 if(s<1){int k=s<.38?20:46;r=g=b=k;}
}
if(d<1){double nx=dx,ny=dy,L=.12*nx-.9*ny;if(L<0)L=0;r=51+(int)(145*L);g=10+(int)(29*L);b=g;}
/* sphere's lower edge is in front of the ground */
fprintf(f,"%d %d %d\n",r,g,b);}fclose(f);return 0;}

